	title 'SANE         FP816         GS ROM 3.0'*****************************************************************			   **	   SANE FP816		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1988	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   ***************************************************************************************************************************************** Change History** 12 Dec 88	Kenton Hanson** Fixed Nan codes (NAN comp and NAN zero).* Fixed conversion error for large comps to exended (in Unpack).* Fixed error signaling error in Floating point NAN converting to*       COMP NAN.***********************************************************************	string asis	blanks off	include 'all.macros'	include '::sys.equs.asm'	include 'sane.macros'SaneVersionNumber	equ $0300True	equ $FFFFFalse	equ $0000;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT oEndCall0	IMPORT oEndCall2	IMPORT Elems816;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY AtoC	ENTRY BtoA	ENTRY BtoC	ENTRY BtoE	ENTRY BtoX	ENTRY CtoB	ENTRY CtoX	ENTRY EtoA	ENTRY EtoB	ENTRY XtoA	ENTRY XtoB	ENTRY CStr2Dec	ENTRY Dec2Str	ENTRY DecStr	ENTRY DnrmC	ENTRY Eight16	ENTRY NrmlzC	ENTRY Rnd2Int	ENTRY SaneShutdown	ENTRY SaneStartup	ENTRY SaneStatus	ENTRY SaneVersion	ENTRY ScaleIt	ENTRY Str2Dec	ENTRY TrpHd1	ENTRY UnPck	ENTRY XitFP	ENTRY add	ENTRY ck4URO	ENTRY mul	ENTRY pck	ENTRY rtnA	ENTRY rtnInf	ENTRY setXcpn	ENTRY sqrt	ENTRY sub	ENTRY B2D	ENTRY D2B	ENTRY Xdiv	ENTRY REM;                copy sane/oequs;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  FPEques;; Description: Equs for ORCA SANE 65816 floating point engine.;; Status: Alpha;;;; Written by Kenton Hanson, Apple Numerics Group, 12 May 1986;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ZPrtn	equ 0OrigDirect	equ ZPrtn+6OrigBank	equ OrigDirect+2base1	equ OrigBank+2	;10opword	equ base1CRgstr	equ base1+2BRgstr	equ base1+6ARgstr	equ base1+10HaltVect	equ base1+14EnvWrd	equ base1+18tmpFlgs	equ base1+20pendingX	equ base1+22pendingY	equ base1+24TmpZP	equ base1+26	;36TmpZP2	equ TmpZP+2TmpZP3	equ TmpZP+4TmpZP4	equ TmpZP+6TmpZP5	equ TmpZP+8fence	equ TmpZP+10fence2	equ TmpZP+12fenceSV	equ TmpZP+14SBWord	equ TmpZP+16	;Max (Sticky Bit Word, length 2nd argument)opcode	equ TmpZP+18ZeroWord	equ TmpZP+20atag	equ TmpZP+22	;identification tag	            (word)	58signA	equ atag+2	;sign	            (word)expnA	equ atag+4	;unbiased exponent	            (Long)lgthA	equ atag+8	;length of Fraction	in bytes    (word)btag	equ atag+10	;identification tag	            (word)signB	equ btag+2	;sign	            (word)expnB	equ btag+4	;unbiased exponent	            (Long)lgthB	equ btag+8	;length of Fraction	in bytes    (word)ctag	equ atag+20	;identification tag	            (word)signC	equ ctag+2	;sign	            (word)expnC	equ ctag+4	;unbiased exponent	            (Long)lgthC	equ ctag+8	;length of Fraction	in bytes    (word)FrctA	equ atag+30	; 88FrctB	equ FrctA+26FrctC	equ FrctA+52len	equ FrctA+78	; 166ilog	equ len+2iscale	equ len+4style	equ len+6digits	equ len+8etag	equ len+10	;identification tag	            (word)	176signE	equ etag+2	;sign	            (word)expnE	equ etag+4	;unbiased exponent	            (Long)lgthE	equ etag+8	;length of Fraction	in bytes    (word)xtag	equ len+20	;identification tag	            (word)signX	equ xtag+2	;sign	            (word)expnX	equ xtag+4	;unbiased exponent	            (Long)lgthX	equ xtag+8	;length of Fraction	in bytes    (word)FrctE	equ len+30	;fraction with binary point after first	bitFrctX	equ len+56	;fraction with binary point after first	bitffExt	equ 0ffDbl	equ 2ffSgl	equ 4ffLng	equ 6ffInt	equ 8ffComp	equ 10ffq	equ 12ffqq	equ 14DnrmTag	equ 1ZeroTag	equ -1InfTag	equ -2NanTag	equ -3SNanTag	equ -4invxcp	equ 01unfxcp	equ 02ovfxcp	equ 04dvzxcp	equ 08inexcp	equ $10NanSqrt	equ $4001NanAdd	equ $4002NanDiv	equ $4004NanMlt	equ $4008NanRem	equ $4009NaNAscB	equ $4011NaNComp	equ $4014	; error codes corrected 12 Dec 88 by KentonNaNZero	equ $4015	; ibidBgnSgDg	equ 4SigDigLn	equ 28	;28 ???;          copy sane/call.table	EXPORT SaneCallTableSaneCallTable	PROC	DC.L (TheEnd-SaneCallTable)/4	DC.L oEndCall0-1	; jumps direct 29 dec 86	DC.L SaneStartup-1	DC.L SaneShutdown-1	DC.L SaneVersion-1	DC.L oEndCall0-1	; jumps direct 29 dec 86	DC.L SaneStatus-1	; added 29 dec 86 by SEG	DC.L oEndCall0-1	DC.L oEndCall0-1	DC.L Eight16-1	DC.L DecStr-1	DC.L Elems816-1TheEnd		; 	ENDP;          copy sane/init.calls******************************************************************* SaneBootInit** Since this does nothing, I put the address of oEndCall0* in the call table.************************************************************************************************************************************* SaneStartup******************************************************************	EXPORT SaneStartupSaneStartup	PROCRTL1	equ 1RTL2	equ RTL1+3ZPToUse	equ RTL2+3	lda ZPToUse,s	phd	; temp store current d	tcd	; set d to SANE value	stz HaltVect	; set default env and HV	stz HaltVect+2	stz EnvWrd	pld	; restore current d	PushWord #0	; system call	PushWord #10	; tool set number	PushWord #0	; High byte of WAP	pha	_SetWAP	jml oEndCall2	ENDP******************************************************************* SaneShutdown******************************************************************	EXPORT SaneShutdownSaneShutdown	PROC	PushWord #0	PushWord #10	PushLong #0	_SetWAP	jml oEndCall0	ENDP******************************************************************* SaneVersion** Uses global version number equate.******************************************************************	EXPORT SaneVersionSaneVersion	PROCRTL1	equ 1RTL2	equ RTL1+3VersionInfo	equ RTL2+3	lda #SaneVersionNumber	EXPORT ShareSTATUSShareSTATUS		;       	sta VersionInfo,s	jml oEndCall0	ENDP******************************************************************* SaneSTATUS** Added by SEG on 29 Dec 86******************************************************************	EXPORT SaneStatusSaneStatus	PROC	cmp #0	beq ShareStatus	lda #True	bra ShareStatus	ENDP******************************************************************* SaneReset** Since this does nothing, I put the address of oEndCall0* in the call table.******************************************************************;          copy sane/dt;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  DT;; Description: Data Constants for ORCA	SANE 65816 floating	point engine;; Status: Alpha;;;; Written by Kenton Hanson, Apple Numerics Group, 13 May 1986;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT DTDT	PROC	EXPORT lastWlastW	DC.W 8,6,2,2,0,6,24,12 ;ext, dbl, sgl, Lng, int, comp, q, q*	EXPORT lastSiglastSig	DC.W 6,6,2,2,0,6,22,10	EXPORT StkBtWdStkBtWd	DC.W 8,6,2,4,2,8,24,12	EXPORT ShftDSShftDS	DC.W 4,7	;right bit shift for word align Dbl+Sgl	EXPORT ExpAdjExpAdj	DC.W 15360,16256	;2^14 - 2^10, 2^14 - 2^7	EXPORT MaxExpMaxExp	DC.W -1,2047,255	EXPORT MinExpMinExp	DC.W 0,15361,16257,16414,16398,16446,0	EXPORT MaxShftMaxShft	DC.W 66,55,26,34,18,66,98,98	EXPORT MaxAdjMaxAdj	DC.W 32767,17407,16511,16414,16398,16446,32767	EXPORT ZINSZINS	DC.B '0INN'	EXPORT RndTblRndTbl	DC.B $00,$00,$00,$c0,$00,$c0,$00,$00,$00,$00,$00,$c0,$00,$c0,$00,$00,$00,$40,$00,$40,$00,$80,$00,$80	ENDP;          copy sane/fp816;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  FP816;; Description: Main routine for ORCA SANE 65816 floating point engine.;; Status: Release 2.0;;;; Written by Kenton Hanson, Apple Numerics Group, 19 May 1986;;;; Modification History: 11Aug86 klh Halt vector mechanism fixed;;	     26Feb87 klh Sets Invalid on integer overflow;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT Eight16Eight16	PROC	jsl IncBusyFlg	phd	; put direct reg on	stack	tcd	; set direct reg	pla	; save orig direct on zp	sta OrigDirect	phb	; save original data bank register	phb	pla	sta OrigBank	; on zero page	phk	; set data bank register	plb	; this bank	bra PassClayton	EXPORT ClaytonClayton		;       ;entry for Elems code	jsl IncBusyFlg	EXPORT PassClaytonPassClayton		; 	pla	sta ZPRtn	pla	sta ZPRtn+2	pla	sta ZPRtn+4	stz ZeroWord	;initialize ZeroWord	stz tmpFlgs	;initialize tmpFlgs	stz Ctag	;initialize Ctag	stz signC	;initialize signC	pla	sta opword	;save opword	xba	tay	and #$7	;location of source	format	asl a	;double it, for word based tables	sta fence	;store source format (usually)	tax	;also store in 'x'	tya	and #$70	;location of destination format	beq z1s1	lsr a	lsr a	lsr az1s1	sta fence2	;format of destination	lda opword	and #$1f	;mask out opcode	sta opcode	tay	;also store in 'y' for NonArith table2	lsr a	;odd values are non	Arithmetic opcodes	bcc z1s2	;Arithmetic function	lda table2-1,y	pha	rtsz1s2	cmp #$7	bcc z1s3	;a < 7, i.e., add, sub, mul, div, cmp, cpx, rem	cmp #$0f	;NextAfter	bne notASMD	ldx fence	stx fence2	;NextAfter, destination gets format of sourcez1s3	stx fenceSv	ldx fence2	stx fence	jsr UnPck	;get second argument (usually extended)	moveA Brgstr,Crgstr	jsr BtoA	ldx fenceSv	;restore fence	stx fence;      ;ldx     fence	ldy StkBtWd,x	;; tmpZP2 := max (lgthA, MaxShft,x)	cpy lgthA	;StkBtWd,x - lgthC	bpl z1s4	ldy lgthAz1s4	sty SBWord	;maximum length, i.e., max (lgthA, MaxShft,x)	jsr UnPck	;get first argument	lda signA	eor signB	sta signC	lda fence2	sta fence	lda #NanTag	cmp Atag	;NanTag - Atag	bpl z1s5	;Nan found	cmp Btag	bmi z1s9	;neither value is a	Nan	bpl z1s7	;only B is Nanz1s5	cmp Btag	;NanTag - Btag	bmi z1s6	;only A is a Nan	lda FrctA	cmp FrctB	;FrctA - FrctB	bcc z1s7	;FrctA < FrctBz1s6	jsr AtoC	sec	bcs z1s8	;branch always !!!!!!!!!z1s11	jsr SetInvz1s12	ldx #$0101	;return value for unordered	stx pendingX	jmp TrpHd1z1s7	jsr BtoCz1s8	lda opcode	cmp #$8	beq z1s12	;cmp	cmp #$0a	beq z1s11	;cpx	jmp rtnArthz1s9	lda rtnA	phanotASMD	ldy opcode	lda table1,y	pha	rts	EXPORT table1table1	DC.W add-1,sub-1,mul-1,Xdiv-1,cmpar-1,cmpar-1,rem-1,z2x-1	DC.W x2z-1,sqr-1,rndti-1,tti-1,scalb-1,logb-1,class-1,next-1	EXPORT rtnArtnA		;       	DC.W rtnArth-1	EXPORT rtnBrtnB		;       	DC.W XitFP-1	EXPORT table2table2	DC.W setE-1,getE-1,setTV-1,getTV-1,D2B-1,B2D-1,neg-1,abs-1	DC.W cpySgn-1,0,SetX-1,ProcIn-1,ProcX-1,testX-1cmpar	pla	;unload rtnA, B rel	A	lda rtnB	phacmpar2	lda Atag	bmi z2s2	lda #-1	bra z2s3	;branch always   !!!!!!z2s2	tax	inx	bmi z2s3	txaz2s3	ldx signA	bne z2s4	eor #-1	;negate 'A'	inc az2s4	sta tmpZP	lda Btag	bmi z2s5	lda #-1	bra z2s6	;branch always   !!!!!!z2s5	tax	inx	bmi z2s6	txaz2s6	ldx signB	bne z2s7	eor #-1	;negate 'A'	inc az2s7	cmp tmpZP	; B - A	bmi z2s15	; B < A	bne z2s17	; B > A	lsr a	bcc z2s13	; B = A	sec	lda expnB	sbc expnA	tay	lda expnB+2	sbc expnA+2	bmi z2s14	; expnB < expnA	bne z2s16	; expnB > expnA	tya	bne z2s16	; expnB > expnA;	            ; expnB	= expnA	ldx lgthB	cpx lgthA	; lgthB - lgthA	bpl z2s10	ldx LgthA	; y := max (lgthB, lgthA)z2s8	stz FrctB,X	dex	dex	cpx lgthB	; x - lgthB	bne z2s8	ldx lgthA	bpl z2s11z2s9	stz FrctA,X	dex	dexz2s10	cpx lgthA	; x - lgthA	bne z2s9	ldx lgthBz2s11	stx tmpZP	ldx #-2z2s12	inx	inx	lda FrctB,x	cmp FrctA,x	; FrctB - FrctA	bcc z2s14	; FrctB < FrctA	bne z2s16	; FrctB > FrctA	cpx tmpZP	; x - tmpZP	bmi z2s12z2s13	ldx #$0002	; B = A	bra endCmpz2s14	lda signB	bne z2s17	;both signs negativez2s15	ldx #$8080	; B < A	bra endCmpz2s16	lda signB	bne z2s15	;both signs negativez2s17	ldx #$4040	; B > AendCmp	stx pendingX	rtsz2x	pop crgstr	;get second argument (usually extended)	jsr UnPck	;get first argument	lda fence2	sta fence	;restore fence to ext. (usually) destination	bra packitx2z	pop crgstr	;get second argument	lda fence	;save fence	sta fenceSv	lda fence2	sta fence	;set fence to extended source	jsr UnPck	;get first argument	(usually extended)	lda fenceSv	;restore fence	sta fencepackit	jsr BtoC	jmp rtnArthsqr	lda fence	sta fence2	jsr UnPck	moveA Brgstr,Crgstr	jsr sqrt	jmp rtnArthscalb	jsr UnPck	moveA Brgstr,Argstr	moveA Brgstr,Crgstr	jsr BtoA	clc	pla	;get scale factor	tax	;save sign of scale	integer	adc expnB	;adjust exponent	sta expnB	txa	bmi z3s7	lda ZeroWord	beq z3s8	;branch always !!!z3s7	lda #-1z3s8	adc expnB+2	sta expnB+2	bra packitrndti	jsr UnPck	moveA Brgstr,Crgstr	jsr BtoC	lda Ctag	bmi z4s1	jsr Rnd2Intz4s1	jmp rtnArthtti	jsr UnPck	moveA Brgstr,Crgstr	jsr BtoC	lda Ctag	bmi z5s1	lda envWrd	sta SBWord	;save rounding direction	ora #$0c000	;set round towards zero	sta envWrd	jsr Rnd2Int	lda SBWord	and #$0c000	sta SBWord	;get original rounding mode	lda envWrd	and #$03fff	ora SBWord	;restore it	sta envWrdz5s1	jmp rtnArthlogb	lda fence	sta fence2	jsr UnPck	moveA Brgstr,Crgstr	lda rtnA	pha	lda Btag	bmi z6s4	lda #$2	sta lgthC	sec	lda expnB	sbc #$3fff	sta FrctC+2	lda expnB+2	sbc zeroWord	sta FrctC	bpl z6s2	sec	lda ZeroWord	sbc FrctC+2	sta FrctC+2	lda ZeroWord	sbc FrctC	sta FrctC	inc signCz6s2	stz expnC+2	lda #$401e	;3fff + 31.	sta expnC	jsr NrmlzC	lda Ctag	bpl z6s3	bit EnvWrd	bpl z6s3	;either round to nearest or upward	bvs z6s3	;round toward zero	inc signC	;round downward with a zero result, rtn	-0z6s3	rtsz6s4	inc a	bne z6s6	;not zero	lda #dvzXcp	jsr setXcpn	inc signC	;return negative infinityz6s5	jmp rtnInf	;jsr, rtsz6s6	inc a	beq z6s5	;infinity found	jmp BtoC	;NaN found return input argumentclass	jsr UnPck	lda Btag	and #$0ff	;clear high byte	asl a	lsr signB	ror a	;put sign in high bit of word	sta pendingX	jmp XitFPnext	jsr cmpar2	txa	and #$0c000	;greater or less than	bne BgNext	jmp AtoC	;jsr, rtsBgNext	stz signB	sta tmpZP	bpl z7s1	inc signB	;negate Bz7s1	eor signA	sta signC	;initialize C for Add	lda envWrd	pha	;save rounding direction	and #$3fff	;clear rounding direction	ora tmpZP	sta envWrd	stz Btag	;put extremely small number in B	stz expnB	lda #$0f000	sta expnB+2	stz lgthB	lda #$8000	sta FrctB	lda Atag	cmp #InfTag	bne z7s2	stz Atag	;put extremely large number in A	stz expnA	lda #$0fff	sta expnA+2	stz lgthA	lda #$8000	sta FrctAz7s2	jsr Add	jsr ck4URO;       ;;;;;;;;;;;;	pla	and #$0c000	sta SBWord	;get original rounding mode	lda envWrd	and #$03fff	ora SBWord	;restore it	sta envWrd	lda tmpFlgs	and #$6	;underflow and overflow	beq z7s5	and #$2	;underflow	bne z7s3	;underflow execption set	lda Ctag	bmi z7s7	;infinity delivered, save flags	bpl z7s5z7s3	lda FrctC	bpl z7s7	;denormal number delivered, save flagsz7s5	stz tmpFlgsz7s7	rts	EXPORT rtnZerortnZero		;       	lda #ZeroTag	bne rtnInf2	EXPORT rtnInfrtnInf		;       	lda #InfTagrtnInf2	sta ctag	lda #-2	sta lgthC	rts	EXPORT InvNanInvNan		;       	stz lgthC	EXPORT InvNan2InvNan2		;       	ora #$4000	;mask in 'non signaling bit'	sta FrctC	lda #NanTag	sta Ctag	EXPORT SetInvldSetInvld		;       ;klh <26Feb87> new entrySetInv	lda #invxcp	EXPORT setXcpnsetXcpn		;       	ora tmpFlgs	sta tmpFlgs	rtsSetE	pla	sta EnvWrd	jmp XitFPGetE	ldx EnvWrd	;!!! Note entire EnvWrd goes to x !!!	stx pendingX	jmp XitFPsetTV	pop HaltVect	jmp XitFPgetTV	ldx HaltVect	stx pendingX	ldy HaltVect+2	sty pendingY	jmp XitFPneg	pop Brgstr	ldy lastW,x	;get word with sign	