ric value	ldx lastSig,y	stx lgthC	lda #-1	; FFFFz16s1	sta FrctC,x	dex	dex	bpl z16s1	dey	dey	bne z16s2	;not a double	lda #$0f800	sta FrctC+6z16s2	dey	dey	bne RtsOut	;not a single	lda #$0ff00	sta FrctC+2	rts;-;+	ENDP;          copy sane/asmdrs;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  ASMDRS;; Description: Add	Subtract Multiply, Divide, Remainder;;              and	Squareroot, for ORCA SANE 65816 floating point engine;; Status: Alpha;;;; Written by Kenton Hanson, Apple Numerics Group, 20 May 1986;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT SubSub	PROC	lda #$1	eor signB	;reverse sign of source	sta signB	eor signA	sta signC	EXPORT AddAdd		;       	ldx Atag	;A - B	bmi z1s3	ldy Btag	bpl BgnAdSb	;no special cases	iny	beq z1s6	;B is zero and A is	a number, return A	bmi z1s4	;B is infinity and A is a number, return Bz1s3	ldy Btag	inx	bmi z1s5	;A is infinity	iny	;A is zero	beq z1s9	;A is zero and B is	zero, return a zero;	            ;A is zero and B is not a zero, return Bz1s4	jmp BtoC	;return Bz1s5	iny	bmi z1s7	;A is infinity and B is infinity, check	signs;	            ;A is infinity and B is not	infinity, return Az1s6	jmp AtoC	;return Az1s7	lda signC	beq z1s6	;signs of infinities are compatible	lda #NanAdd	jmp InvNanz1s9	lda signC	beq z1s6	;sum of zeros with same sign	jmp ZrRslt	;0-0 or 0+(-0), ck rounding direction for signBgnAdSb	sec	lda expnA	sbc expnB	sta expnX	lda expnA+2	sbc expnB+2	sta expnX+2	bmi AxltBx	;expnA < expnB;	            ;expnA >= expnB	RtoRXpn B,C,A	;B to C with sign &	exponent of A	jmp DMC	;Branch always !!!!!!!!!!!!!!!!!!	EXPORT AxltBxAxltBx		; 	RtoRXpn A,C,B	;A to C with sign &	exponent of B	lda signA	sta signB	ldx lgthB	stx lgthAz2s1	lda FrctB,x	sta FrctA,x	dex	dex	bpl z2s1	ldx fence	ldy StkBtWd,x	;; SBWord := max (lgthA, MaxShft,x)	cpy lgthA	;StkBtWd,x - lgthA	bpl z2s3	ldy lgthAz2s3	sty SBWord	;maximum length, i.e., max (lgthA, MaxShft,x)	sec	;expnX := -expnX	lda ZeroWord	sbc expnX	sta expnX	lda ZeroWord	sbc expnX+2	sta expnX+2DMC	jsr dnrmC	ldx lgthCz3s1	cpx lgthA	;lgthC - lgthA	bpl z3s2	inx	inx	stx lgthC	;extend length of C	to A	stz FrctC,X	bpl z3s1	;branch always  !!!!!!!!!!!!!!!!z3s2	lda signB	eor signC	bne diffSgn	ldx lgthA	clcz3s5	lda FrctA,x	adc FrctC,x	sta FrctC,x	dex	dex	bpl z3s5	bcc z3s10	;no carry overflow	ldx lgthC	txy	ldx ZeroWordz3s6	ror FrctC,x	inx	dey	inx	dey	bpl z3s6	inc expnC	;adjust exponent	bne z3s7	inc expnC+2z3s7	bcc z3s10	;no carry from right bit shift	ldx lgthC	cpx SBWord	;lgthC - SBWord	bcc z3s8	;lgthC < SBWord	lda FrctC,x	ora #$1	;or carry out, into	last bit of FrctC,x	bne z3s9	;always truez3s8	inx	;add new word with a leading bit set	inx	stx lgthC	inc tmpZP2	;update word length	lda #$8000z3s9	sta FrctC,xz3s10	rtsdiffSgn	ldx lgthAz4s1	cpx lgthC	;lgthA - lgthC	bpl z4s2	inx	inx	stx lgthA	;extend length of A	to C	stz FrctA,X	bpl z4s1	;branch always  !!!!!!!!!!!!!!!!z4s2	secz4s5	lda FrctA,x	sbc FrctC,x	sta FrctC,x	dex	dex	bpl z4s5	bcs NrmlzC	;|A| >= |C|	ldx lgthC	;negate result	secz4s6	lda ZeroWord	sbc FrctC,x	sta FrctC,x	dex	dex	bpl z4s6	lda signB	;change sign	sta signC	EXPORT NrmlzCNrmlzC		;       	lda FrctC	bne NrmBitC	;leading word non zero	ldx #-2	lda lgthC	beq ZrRslt	;zero result	lsr a	;number of word shiftsz5s1	inx	inx	ldy FrctC+2,x	sty FrctC,x	dec a	bne z5s1	stx lgthC	;store updated length of C	lda expnC	;Note: carry cleared by 'lsr' above	sbc #$0f	;really expnC := expnC - 16.	sta expnC	bcs NrmlzC	dec expnC+2	bcc NrmlzC	;branch alwaysZrRslt	stz signC	lda EnvWrd	and #$0c000	;mask in rounding direction	asl a	bcc z6s1	bne z6s1	;RZ	rol signCz6s1	jmp rtnZeroloopNBC	ldx lgthC	clcz7s3	rol FrctC,x	dex	dex	bpl z7s3	lda expnC	bne z7s4	dec expnC+2z7s4	dec expnC	lda FrctCNrmBitC	bpl loopNBC	rts;	            ;A div B	EXPORT XdivXdiv		;       	ldx Atag	bmi z8s5	ldy Btag	bpl BgnDiv	;no special cases	iny	bmi z8s6	;B is infinity and A is a number, return zero;	            ;B is zero and A is a number, return infinity	lda #dvzxcp	jsr setXcpn	;signal div_zeroz8s4	jmp rtnInfz8s5	cpx Btag	beq z8s7	;0/0 or infinity/infinity	inx	bmi z8s4	;A is infinity and B is not, return infinity;	            ;A is zero and B is not zero, return zeroz8s6	jmp rtnZeroz8s7	lda #NanDiv	jmp InvNanBgnDiv	jsr rtab1X	;right shift A and B one bit;	            ;& extend the length of A to B if necessary	ldx fence2	;format of destination	lda MaxShft,x	sta tmpZP2	lsr tmpZP2	;divide by 16, to find the # of word divides	lsr tmpZP2	lsr tmpZP2	lsr tmpZP2	;number of full word divides	and #$0f	sta tmpZP3	;number of bit divides for last word	stz lgthC	;initialize length of 'C'z9s4	jsr dvword	;divide a word	ldx lgthC	lda tmpZP	sta FrctC,x	;store byte of quotient	inc lgthC	inc lgthC	dec tmpZP2	bne z9s4	ldy tmpZP3	jsr dvword2	lda tmpZP	lsr az9s5	ror a	;adjust last word of quotient	dec tmpZP3	bne z9s5	ldx lgthC	sta FrctC,x	;store word of quotient	ldx lgthAz9s7	lda FrctA,x	;check for sticky bit loop	bne z9s8	;found a sticky bit	dex	dex	bpl z9s7	bmi z9s9	;branch always, no sticky bitz9s8	ldx lgthC	lda #$1	ora FrctC,x	;or in sticky bit	sta FrctC,x	;store sticky bitz9s9	sec	lda expnA	sbc expnB	sta expnC	lda expnA+2	sbc expnB+2	sta expnC+2	lda FrctC	asl a	bcs z9s13	;leading bit set, no left shift necessary	ldx lgthC	clcz9s12	rol FrctC,x	dex	dex	bpl z9s12z9s13	lda expnC	;adjust exponent	adc #$3ffe	sta expnC	lda expnC+2	adc ZeroWord	sta expnC+2z9s15	ldx lgthC	;strip trailing zero word loop	lda FrctC,x	bne z9s20	;word contains a bit, exit loop	dec lgthC	dec lgthC	bpl z9s15z9s20	rtsdvword	ldy #$10	;set bit counterdvword2	stz tmpZP	;initialize quotient worddvword3	lda FrctA	cmp FrctB	;compares MSB of FrctA - FrctB	bcc z10s4	;early bypass, FrctA < FrctB	ldx lgthB	;carry is setz10s2	lda FrctA,x	sbc FrctB,x	;FrctA := FrctA - FrctB loop	sta FrctA,x	dex	dex	bpl z10s2	bcs z10s4	;FrctA - FrctB >= 0	ldx lgthB	;carry is clearz10s3	lda FrctA,x	adc FrctB,x	;restore loop	sta FrctA,x	dex	dex	bpl z10s3	clcz10s4	rol tmpZP	ldx lgthA	clcz10s5	rol FrctA,x	;left shift 'A'	dex	dex	bpl z10s5	dey	;decremet bit counter	bne dvWord3	rtsrtab1X	ldx ZeroWord	;shift anm "1" bit to right ********	lda lgthA	lsr a	;divide by 2, i.e. number of words in 'A';      ;clc	            ;Note:	above instruction clears carryz11s1	ror FrctA,x	;right shift byte	inx	inx	dec a	bpl z11s1	bcc rtb1	;no carry bit	stx lgthA	;store incremented anm	stz FrctA,X	ror FrctA,x	;shift in carryrtb1	ldx ZeroWord	;shift anm "1" bit to right ********	lda lgthB	lsr a	;divide by 2, i.e. number of words in 'B';      ;clc	            ;Note:	above instruction clears carryz12s1	ror FrctB,x	;right shift byte	inx	inx	dec a	bpl z12s1	bcc XAtoB	;no carry bit	stx lgthB	;store incremented anm	stz FrctB,X	ror FrctB,x	;shift in carryXAtoB	ldx lgthAz13s1	cpx lgthB	;lgthA - lgthB	bcs z13s2	;lgthA >= lgthB	inx	inx	stx lgthA	;store new length	stz FrctA,X	;pad FrctA with zeros	bpl z13s1	;always truez13s2	rts	EXPORT remrem		;       	lda signC	lsr a	stz pendingX	;put sign of C into	pendingX	ror pendingX	;in the high bit of	both bytes	xba	ora pendingX	sta pendingX	lda signA	sta signC	;initialize sign	lda atag	ldx btag	bmi z14s1	tay	bpl BgnRem	;no special casesz14s1	cmp #inftag	beq z14s2	;g,h,i          infinity rem [ ]	cpx #ZeroTag	beq z14s2	;a,d            [ ]	rem 0	jmp AtoC	;rts     b,c,f	    0 rem [w, infinity];		    ;or w rem infinityz14s2	lda #NaNRem	jmp invNaN	;rtsBgnRem	jsr rtab1X	;right shift A and B one bit;	            ;& extend the length of A to B if necessary	stz tmpZP	sec	lda expna	sbc expnb	sta expnc	lda expna+2	sbc expnb+2	sta expnc+2	inc expnC	;add 1	bne z15s2	inc expnC+2z15s2	bit expnC+2	bmi z15s13	ldy #$1	jsr dvword2	ldy expnC	beq z15s3	jsr dvword3z15s3	dec expnc+2	;sub 1	bmi z15s5	ldy ZeroWord	jsr dvword3	;i.e. do 2^16 cycles	bra z15s3	;always truez15s5	clc	;subtract 1	lda ExpnB	sbc ZeroWord	sta ExpnC	lda ExpnB+2	sbc ZeroWord	sta ExpnC+2	lsr tmpZP	lda tmpZP	sta tmpZP4	bcc z15s23	;a < b/2	ldx lgthAz15s7	lda FrctA,x	bne z15s8	;non zero anm	dex	dex	bpl z15s7	lsr tmpZP	bcc z15s9	;Q is evenz15s8	lda tmpZP4	;carry is set	adc ZeroWord	;clears carry, for $9 below	sta tmpZP4	lda signC	eor #$1	;change sign	sta signCz15s9	ldx lgthB;      ;clcz15s10	rol FrctB,x	dex	dex	bpl z15s10	ldx lgthBz15s22	cpx lgthA	bcs z15s11	; x >= lgthA	inx	inx	stz FrctB,X	bpl z15s22	; always truez15s11	lda FrctB,x	sbc FrctA,x	;a := b - a	sta FrctA,x	dex	dex	bpl z15s11z15s23	lda tmpZP4	and #$7f	ora pendingX	sta pendingX	ldx lgthAz15s12	lda FrctA,x	bne z15s15	dex	dex	bpl z15s12	jmp rtnZero	;rtsz15s13	sec	;add 1	lda expnA	adc ZeroWord	sta expnC	lda expnA+2	adc ZeroWord	sta expnC+2z15s15	ldx lgthA	stx lgthCz15s16	lda FrctA,x	sta FrctC,x	dex	dex	bpl z15s16	tax	bmi EndRem	EXPORT BgnNrmCBgnNrmC		;       	ldx lgthC	;left shift one bit	clcz16s1	rol FrctC,x	dex	dex	bpl z16s1	lda expnC	;increment exponent	bne z16s2	dec expnC+2z16s2	dec expnCnormC	lda FrctC	bpl BgnNrmC	;still not normalizedTailOff	ldx lgthC	bmi EndRemz17s1	lda FrctC,x	;strip trailing zero words	bne EndRem	dex	dex	stx lgthC	bpl z17s1EndRem	rts	EXPORT sqrtsqrt		;       	lda signB	sta signC	beq z18s3	;positive argument	lda Btag	bpl z18s1	;sqrt of non zero negative number	cmp #Inftag	bne z18s2	;either '0' or a Nanz18s1	lda #NanSqrt	jmp InvNaN	;rtsz18s2	jmp BtoC	;rtsz18s3	lda Btag	bmi z18s2	jsr rtB1	clc	lda #$4001	;(3fff + 2)	adc expnB	;adjust exponent and transfer to expnC	sta expnC	lda ZeroWord	adc expnB+2	sta expnC+2	lda expnC+2	asl a	;extend sign	ror expnC+2	ror expnc	bcs z18s5	jsr rtB1z18s5	ldx fence	ldy MaxShft,x	lda #$2000	stz lgthC	;initialize lgthC	ldx lgthC	sta FrctC	sta tmpZP	;initialize tmpZP	beq z18s12	;always truez18s8	lsr tmpZP	;right shift mask	bcc z18s10	;mask ok	lda #$8000	sta tmpZP	;reset mask	inc lgthC	;expand lgthC	inc lgthC	ldx lgthC	stz FrctC,X	ldx lgthB	cpx lgthC	bcs z18s9	;lgthB ok	inx	inx	stx lgthB	;expand lgthB	stz FrctB,Xz18s9	clcz18s10	ldx lgthBz18s11	rol FrctB,x	;left shift FrctB 1	bit	dex	dex	bpl z18s11	ldx lgthC	lda FrctC,x	ora tmpZP	sta FrctC,x	;or mask with FrctCz18s12	lda FrctB	cmp FrctC	bcc z18s16	;early bypass	ldx lgthCz18s13	lda FrctB,x	;subtact loop	sbc FrctC,x	sta FrctB,x	dex	dex	bpl z18s13	ldx lgthC	bcc z18s15	;lgthB < lgthC	clc	lda tmpZPz18s14	adc FrctC,x	;add mask i.e. really 2*mask	sta FrctC,x	bcc z18s17	lda ZeroWord	dex	dex	bpl z18s14z18s15	lda FrctB,x	adc FrctC,x	;restore FrctB loop	sta FrctB,x	dex	dex	bpl z18s15z18s16	ldx lgthC	lda tmpZP	eor FrctC,x	;restore FrctC	sta FrctC,xz18s17	dey	bpl z18s8	;need another bit	ldx lgthBz18s18	lda FrctB,x	bne z18s19	;sticky bit found	dex	dex	bpl z18s18	bmi z18s20	;always true, no sticky bit foundz18s19	ldx lgthC	lda tmpZP	ora FrctC,x	;insert sticky bit	sta FrctC,xz18s20	jmp BgnNrmC	;rts	ENDP;          copy sane/b2d2b;he     ''B2D2B'17 April 86;fo     ''%'klh;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  B2D2B;; Description: Binary <--> Decimal for	ORCA SANE 65816 floating point engine;; Status: Alpha;;;; Written by Kenton Hanson, Apple Numerics Group, 17 April	1986;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT B2DB2D	PROC	pop Argstr	;pointer to decimal	record	jsr UnPck	;pointer to source (Brgstr)	pop Crgstr	;pointer to format record	ldy ZeroWord	lda [Crgstr],y	sta style	lda signB	sta [Argstr],y	iny	iny	lda [Crgstr],y	sta digits	lda Btag	bpl NzFnVal	;Nonzero Finite Value	longa off	longi off	sep #$30	eor #$0ff	;negate Btag and subtract 1	tax	lda ZINS,x	;get character for zero, infinity or NaN	ldy #BgnSgDg+1	sta [argstr],y	cpx #$02	lda #$01	bcc z1s3	;x < 2	ldx lgthB	inx	inx	stx TmpZP	;lgthB + 2	ldx #$00z1s2	lda FrctB+1,x	lsr a	lsr a	lsr a	lsr a	jsr Nib2Hex	lda FrctB+1,x	and #$0f	jsr Nib2Hex	lda FrctB,x	lsr a	lsr a	lsr a	lsr a	jsr Nib2Hex	lda FrctB,x	and #$0f	jsr Nib2Hex	inx	inx	cpx TmpZP	bcc z1s2	;x < lgthB + 2	tya	sbc #BgnSgDg	;carry was setz1s3	ldy #BgnSgDg	sta [argstr],y	rep #$30	jmp TrpHd1	;rts	sep #$30Nib2Hex	cmp #$0a	bcs z2s5	;a > 9	ora #$30	bcc z2s6	;always truez2s5	adc #$56z2s6	iny	sta [argstr],y	rts	longa on	longi on	rep #$30NzFnVal	lda #ffqq	sta fence2	;max precision for scaled integer	lda style	bne z3s9	;style is fixed	lda digits	bmi z3s8	;digits < 0	bne z3s9	;digits > 0z3s8	stz digits	inc digits	;set digits to 1z3s9	jsr BtoE	;save B, restore if	length > len	jsr fplog10	;get a floor log10 of source, (ilog)b2dLoop	sec	lda style	bne z4s11	;style is fixed	lda digits	sta len	;len := digits	bcs z4s12	;always true !!!!!!!!!!!!z4s11	lda ilog	adc digits	sta len	;len := ilog + digits + 1z4s12	bmi z4s13	;len < 0	sec	;len > SigDigLn ?	lda #SigDigLn	sbc len	bpl z4s13	;no	lda #SigDigLn	sta len	;len := SigDigLnz4s13	clc	lda len	sbc ilog	sta iscale	;iscale := len - ilog - 1	sta tmpZP	lda len	bmi z4s91	bne z4s92z4s91	stz len	;len < 1, len := 1	inc lenz4s92	ldy #$02	sec	lda ZeroWord	sbc iscale	sta [argstr],y	;exp := ilog + 1 - len (= -iscale)	jsr ScaleIt	jsr Rnd2IntI2ASCII	stz FrctA	;initialize FrctA	stz lgthA	lda Ctag	bmi z5s9	;case of integer zero	stz tmpZP3	;number of words in	FrctA	sec	lda expnC	sbc #$3fff	sta tmpZP5	and #$0f	sta tmpZP4	;number of bits in last word	lsr tmpZP5	lsr tmpZP5	lsr tmpZP5	lsr tmpZP5	;location of last word	stz lgthX	;initialize pointer	to Frctc	SED	;set decimal modez5s2	ldx lgthX	cpx lgthC	;lg