riginal signed iscale	rol fenceSv	;get sign of iscale	into pointer	lda signB	lsr a	rol fenceSv	;get sign of sign into pointer	rol fenceSv	ldx fenceSv	lda RndTbl-8,x	eor EnvWrd	;alter rounding direction according to	sta EnvWrd	;the Rounding Table, xz6s3	jsr ten	lda signE	sta signC	jsr EtoA	lda #$3fff	and EnvWrd	sta EnvWrd	pla	ora EnvWrd	;restore rounding direction	sta EnvWrd	ldx fence2	stx fence	ldy StkBtWd,x	;; tmpZP2 := max (lgthA, MaxShft,x)	cpy lgthA	;StkBtWd,x - lgthC	bpl z6s4	ldy lgthAz6s4	sty SBWord	;maximum length, i.e., max (lgthA, MaxShft,x)	bit tmpZP5	;get original signed -iscale	bpl z6s5	;exp > 0	jmp mul	;jsr & rtsz6s5	jmp Xdiv	;jsr & rtsFPLog10	lda #$9a1f	;1 less than 2*log2, carry set below	sta tmpZP	sec	lda expnB	sbc #$3fff	;unbias exponent into twos complement form	tay	sta tmpZP2	sta tmpZP3	;used to generate sign extend below	bpl z7s1	inc tmpZP	;increment log2 if unbiased exponent < 0z7s1	lda FrctB	sta tmpZP4	lda ZeroWord	ldx #$0fz7s2	lsr tmpZP4	;multiply fraction part times log2	bcc z7s3	adc tmpZP	;note carry is set (see comment above)z7s3	ror a	dex	bne z7s2	ldx #$11	asl tmpZP3z7s4	ror tmpZP2	;multiply exponent part times log2	bcc z7s5	adc tmpZP	;note carry is set (see comment above)z7s5	ror a	dex	bne z7s4	tyx	bpl z7s6	clc	sbc tmpZP	;really add of (2^inf - 1)*tmpZPz7s6	sta ilog	;store ilog	rtsTen	lda iscale	jsr ten15	lsr iscale	lsr iscale	lsr iscale	lsr iscale	bne z8s1	;iscale > 15	rtsz8s1	ldx #ffqq	stx fence	lda stkBtWd,x	sta SBWord	jsr BtoX	stz signC	;set sign of result	lda #$10	jsr tableX	jmp z8s4z8s2	jsr XtoB	jsr CtoXz8s3	jsr BtoA	jsr mul	jsr ck4URO	jsr CtoBz8s4	lsr iscale	bcc z8s3	jsr XtoA	jsr BtoX	jsr mul	jsr ck4URO	lda iscale	bne z8s2	jmp CtoB	;rtsten15	and #$0ftableX	asl a	;multiply table entry by ten	sta tmpZP	asl a	asl a;       ;clc	            ;assume	carry is clear	adc tmpZP	tay	;and store in y	stz Btag	stz signB	stz expnB+2	lda XTable+8,y	asl a	rol signB	lsr a	sta expnB	ldx #$6	lda XTable+6,y	sta FrctB	lda XTable+4,y	sta FrctB+2	lda XTable+2,y	sta FrctB+4	lda XTable,y	sta FrctB+6	bne z9s2z9s1	dex	dex	lda FrctB,x	beq z9s1z9s2	stx lgthB	rts	EXPORT XTableXTable	DC.W 0,$0,$0,$8000,$3FFF	DC.W 0,$0,$0,$0A000,$4002	DC.W 0,$0,$0,$0C800,$4005	DC.W 0,$0,$0,$0FA00,$4008	DC.W 0,$0,$0,$9C40,$400C	DC.W 0,$0,$0,$0C350,$400F	DC.W 0,$0,$0,$0F424,$4012	DC.W 0,$0,$8000,$9896,$4016	DC.W 0,$0,$2000,$0BEBC,$4019	DC.W 0,$0,$2800,$0EE6B,$401C	DC.W 0,$0,$0F900,$9502,$4020	DC.W 0,$0,$0B740,$0BA43,$4023	DC.W 0,$0,$0A510,$0E8D4,$4026	DC.W 0,$0,$0E72A,$9184,$402A	DC.W 0,$8000,$20F4,$0B5E6,$402D	DC.W 0,$0A000,$0A931,$0E35F,$4030	DC.W 0,$0400,$0C9BF,$8E1B,$4034	EXPORT Rnd2IntRnd2Int		;       	stz tmpZP2	;least significant bit	stz tmpZP	;round bit	sec	lda expnC	;find the bit location to the right of the	sbc #$3fff	;lsb, with respect to msb of FrctC	sta expnX	;store it in expnX	lda expnC+2	sbc ZeroWord	sta expnX+2	bpl z10s4	;least bit inside left side of FrctC	ldx ZeroWord	;set word location of first search	lda #$0ffff	cmp expnX	bne z10s10	;lsb miles to the left of msb of FrctC	cmp expnX+2	bne z10s10	;lsb to the left of	msb of FrctC	lda #$8000	;round bit just left of FrctC	bne z10s8	;check round bit, branch always !!!!!!!z10s3	rtsz10s4	lda expnX	;make bit mask	and #$0f	tax	sec	lda ZeroWordz10s5	ror a	dex	bpl z10s5	sta tmpZP4	tay	;save mask in y	lsr ExpnX+2	;calculate word location of lsb	ror ExpnX	lsr ExpnX+2	ror ExpnX	lsr ExpnX+2	ror ExpnX	ror ExpnX	asl ExpnX	ldx ExpnX+2	bne z10s3	;binary point is miles to the right	ldx ExpnX	cpx lgthC	;ExpnX - lgthC	beq z10s7	bcs z10s3	;decimal point beyond FrctCz10s7	and FrctC,x	sta tmpZP2	;save lsb	tya	lsr a	bne z10s8	;not crossing word boundry	ror a	;crossing a word boundry, take special action	cpx lgthC	;x - lgthC	bpl z10s3	;no Round or Sticky	bits	inx	inxz10s8	tay	;check the round bit	and fr