gine;; Status: ROM 2.0 and them some.;;;; Written by Kenton Hanson, Apple Numerics Group, 16 May 1986;;;; Modification History;;;;    23 mar 87	  Kenton Hanson;;;;       Sticky bit	word error in multiply corrected.;; ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT D2BD2B	PROC;       ;ldx    fence           ;done in 'fp816'	stx fence2	;set destination format	pop Crgstr	;pointer to destination	pop Argstr	;pointer to decimal	record	lda rtnA	pha	;push 'rthArth' as return address	stz signB	stz signC	ldy ZeroWord	lda [Argstr],y	beq z1s0	inc signB	inc signCz1s0	ldy #BgnSgDg	;relative location of SigDig in Decimal	lda [Argstr],y	and #$0ff	beq z1s99	;NULL string, return zero	sta len	iny	sty tmpZP	;initialize string pointer	cmp #SigDigLn+1	bcc z1s1	;a <= SigDigLn	lda #SigDigLn	clcz1s1	adc #BgnSgDg	sta tmpZP2	;initialize end location of string in record	lda [Argstr],y	and #$0ff	cmp #$30	;ASCII zero	bne z1s2z1s99	jmp rtnZero	;jsr & rtsz1s2	and #$0df	cmp #$49	;ASCII 'i' or 'I'	bne z1s22	jmp RtnInfz1s22	cmp #$4e	;ASCII 'n' or 'N'	bne gtdgts	lda #NaNtag	sta Ctag	stz lgthC	;initialize FrctC	stz FrctC	ldx lgthC	inc tmpZP2	stz tmpZP3	;flag for next wordz1s3	iny	cpy tmpZP2	bcs z1s5	;tmpZP >= tmpZP2	sep #$30	lda [Argstr],y	rep #$30	and #$00ff	cmp #$41	;'A'	bcc z1s4	;a < 'A'	adc #$8	;carry was set, i.e., a := a + 9z1s4	and #$0f	;get low order nibble	cpy #BgnSgDg+6	beq The6th	asl tmpZP3	bcs The6thMoreNaN	asl FrctC,x	asl FrctC,x	asl FrctC,x	asl FrctC,x	ror tmpZP3	;next word flag	ora FrctC,x	sta FrctC,x	bra z1s3	;always trueThe6th	inx	inx	stx lgthC	stz FrctC,x	inc FrctC,x	bra MoreNaNz1s5	txa	beq z1s7	;1st word, don't left justify	bit tmpZP3	bmi z1s7z1s6	asl FrctC,x	bcc z1s6z1s7	lda #$4000	;bit for signaling NaN	bit FrctC	; *** 21 March 1985	***	bne z1s8	;not a signaling NaN	lda FrctC	jmp InvNaN2	;jsr & rtsz1s8	lda FrctC	and #$0ff	bne z1s9	;Non zero NaN code found	lda #NaNZero	ora FrctC	sta FrctCz1s9	rtsgtdgts	stz lgthB	;initialize FrctB	stz FrctB	stz Btag	;intialize tag	ldy #$2	lda [Argstr],y	sta iscale	;get exponent into iscale	bpl z2s12	;do not need to strip trailing ASCII zerosz2s3	ldy tmpZP2	sep #$30	lda [Argstr],y	rep #$30	and #$0f	;change ASCII digit	to binary	bne z2s12	;no more trailing zeros	dec tmpZP2	inc iscale	bmi z2s3	;iscale still < 0	bpl z2s12z2s4	dec iscale	;iscale := iscale -	1z2s5	lda FrctB	and #$0e000	beq z2s6	;no byte shift necessary	jsr rtWord	stz FrctBz2s6	ldx lgthB	;multiply by 10	clcz2s7	lda FrctB,x	rol a	sta FrctA,x	sta FrctB,x	dex	dex	bpl z2s7	ldy #$2z2s8	ldx lgthBz2s9	rol FrctB,x	dex	dex	bpl z2s9	dey	bne z2s8	ldx lgthBz2s10	lda FrctA,x	adc FrctB,x	sta FrctB,x	dex	dex	bpl z2s10	bcc z2s11	jsr rtWordz2s11	ldy tmpZP	cpy tmpZP2	inc tmpZP	bcc z2s12	;tmpZP <= tmpZP2	ldy tmpZP	bcs z2s14	;always truez2s12	ldy tmpZP	sep #$30	lda [Argstr],y	rep #$30	and #$0f	;change ASCII digit	to binary	ldx lgthB	clcz2s13	adc FrctB,x	sta FrctB,x	bcc z2s14	lda ZeroWord	dex	dex	bpl z2s13	jsr rtWordz2s14	cpy tmpZP2	bcc z2s5	;y < tmpZP2	lda iscale	beq z2s15	;iscale = 0	bmi z2s15	;iscale < 0, appending zeros does no good	cpy #BgnSgDg+SigDigLn	bcc z2s4	;y < SigDigLn, append zeroz2s15	lda FrctB	bne z2s17z2s16	jmp rtnZero	;jsr & rtsz2s17	lda lgthB	asl a	;multiply by 8	asl a	asl a;      ;clc	adc #$400e	;add bias (3fff) + 16. - 1	sta expnB	stz expnB+2	bit FrctB	bmi z2s18	;already normalized	jsr BgnNrmBz2s18	jsr BtoE	lda iscale	sta tmpZP	;save original iscale	eor #$0ffff	inc a	;-iscale	jmp ScaleIt	;jsr, rtsrtWord	ldx lgthB	cpx #FrctC-FrctB	bcs z3s2	;cnm >= 13, don't overwrite memory	inc lgthB	;increase length of	lgthB	inc lgthBz3s1	lda FrctB,x	sta FrctB+2,x	dex	dex	bpl z3s1	lda #$1	sta FrctB	rtsz3s2	lda #NanAscB	;Invalid dec -> bin	conversion: syntax	pla	;to prevent returning to digit gathering code	jmp invNaN	;rts	EXPORT MulMul		;       	ldx Atag	bmi z4s3	ldy Btag	bpl BgnMlt	;no special cases	iny	beq z4s4	;B is zero and A is	a number, return zero	bmi z4s6	;B is infinity and A is a number, rtn infinityz4s3	ldy Btag	inx	bmi z4s5	;A is infinity	iny	;A is zero	bmi z4s7	;A is zero and B is	infinity, return invalid;	            ;A is zero and B is not infinity, return zeroz4s4	jmp rtnZeroz4s5	iny	beq z4s7	;A is infinity and B is zero, return invalid;	            ;A is infinity and B is non	zero, rtn Infinityz4s6	jmp rtnInfz4s7	lda #NanMlt	jmp InvNan	EXPORT BgnMltBgnMlt		; ;--------------------------------------------------; Added 23 Mar 87 to fix problem with multiplies; of numbers with different formats.  Result was; not coming back in extended.; 	ldx Fence	ldy stkBtWd,x	sty SBWord; ; End of addition ;-------------------------------------------------- 	ldx lgthA	stx lgthC	stx tmpZP2	lsr tmpZP2	;current word count	for FrctCz5s2	stz FrctC,X	;initialize C	dex	dex	bpl z5s2z5s3	ldx lgthB	lda frctB,x	sta tmpZP	ldy #$0fz5s4	lsr tmpZP	bcc z5s6	clc	ldx lgthAz5s5	lda FrctC,x	adc FrctA,x	sta FrctC,x	dex	dex	bpl z5s5z5s6	lda tmpZP2	;get current word count for FrctC	ldx ZeroWordz5s7	ror Frctc,x	;Note, carry is correct for first shift	inx	inx	dec a	bpl z5s7	bcc z5s10	;no carry propagation	ldx lgthC	cpx SBWord	;lgthC - SBWord	bcc z5s8	;lgthC < SBWord	lda FrctC,x	ora #$1	;or carry out, into	last bit of FrctC,x	bne z5s9	;always truez5s8	inx	;add new word with a leading bit set	inx	stx lgthC	inc tmpZP2	;update word length	lda #$8000z5s9	sta FrctC,xz5s10	dey	bpl z5s4	dec lgthB	dec lgthB	bpl z5s3	clc	lda expnA	adc expnB	sta expnC	lda expnA+2	adc expnB+2	sta expnC+2	lda FrctC	asl a	bcs z5s13	;leading bit set, no left shift necessary	ldx lgthC	clcz5s12	rol FrctC,x	dex	dex	bpl z5s12z5s13	lda expnC	;adjust exponent	sbc #$3ffe	sta expnC	lda expnC+2	sbc ZeroWord	sta expnC+2z5s15	ldx lgthC	;strip trailing zero word loop	lda FrctC,x	bne z5s20	dec lgthC	dec lgthC	bpl z5s15z5s20	rts	EXPORT DnrmCDnrmC		;       	ldx fence	lda expnX+2	;contains hi word of number of right shifts	bne z6s2	;do max shift	lda expnX	;expnX contains low	word of # of right shifts	bne z6s1	rts	;no shiftingz6s1	cmp MaxShft,x	bcc z6s3	;a < MaxShft,xz6s2	lda MaxShft,x	;stuff maximum shift into expnX	sta expnXz6s3	ldy StkBtWd,x	;; tmpZP2 := max (lgthC, MaxShft,x)	cpy lgthC	;StkBtWd,x - lgthC	bpl z6s4	ldy lgthCz6s4	sty tmpZp2	;maximum length, i.e., max (lgthC, MaxShft,x)BitShft	stz tmpZP3	;left storage word for bit shift	lda expnX	;number of right shifts	and #$0f	beq WrdShft	;no bit shift	cmp #$9	bcc z7s3	;a < 9z7s1	ldx lgthC	clcz7s2	rol FrctC,x	dex	dex	bpl z7s2	rol tmpZP3	inc expnX	lda expnX	and #$0f	bne z7s1	beq WrdShftz7s3	ldx ZeroWord	clcz7s4	ror FrctC,x	txa	eor lgthC	beq z7s5	inx	inx	bne z7s4	;branch always  branch always  branch alwaysz7s5	bcc z7s9	cpx tmpZP2	bpl z7s7	;x >= tmpZP2 (i.e.,	StkBtWd,x)	inx	inx	stx lgthC	lda #$8000	bne z7s8	;branch always  branch always  branch alwaysz7s7	lda FrctC,x	ora #$1	;or in sticky bitz7s8	sta FrctC,xz7s9	dec expnX	lda expnX	and #$0f	bne z7s3WrdShft	stz tmpZP4	;bucket for sticky words	lda expnX	;number of bits to be shifted	lsr a	lsr a	lsr a	lsr a	beq ckTail	;no word shift	tay	;number of word shiftsz8s3	ldx lgthC	cpx TmpZP2	;x - MaxlgthC	bmi z8s4	;x < MaxlgthC	lda FrctC,x	beq z8s6	sta tmpZP4	;sticky word found,	save it	bne z8s6z8s4	inc lgthC	inc lgthCz8s5	lda FrctC,x	;right shift one word loop	sta FrctC+2,xz8s6	dex	dex	bpl z8s5	lda tmpZP3	;on first pass use original value	sta FrctC	stz tmpZP3	;thereafter, fill from the left with zero words	dey	bne z8s3ckTail	lda tmpZP4	beq z9s7	;nothing in sticky word bucket	ldx lgthC	lda FrctC,x	ora #$1	;insert sticky bit	sta FrctC,x	bne z9s8	;branch alwaysz9s7	ldx lgthC	lda FrctC,x	bne z9s8	dec lgthC	dec lgthC	bpl z9s7z9s8	rts	ENDP;          copy sane/dcstr	EXPORT DecStrDecStr	PROC	jsl IncBusyFlg	phd	; put direct reg on	stack	tcd	; set direct reg	pla	; save orig direct on zp	sta OrigDirect	phb	; save original data bank register	phb	pla	sta OrigBank	; on zero page	phk	; set data bank register	plb	; this bank	pla	sta ZPRtn	pla	sta ZPRtn+2	pla	sta ZPRtn+4FOPSTR2DEC	EQU 0	; Pascal string to decimal recordFOCSTR2DEC	EQU 2	; C string to decimal recordFODEC2STR	EQU 1	; decimal record to	string;      ;.proc   DecStr;      ;.ref    Str2Dec,Dec2Str,CStr2Dec	plx	;put opcode into 'x'	lda rtnB	;address of XitFP	pha	cpx #FODEC2STR	;opcode - #FODEC2STR	bpl z1s3	jmp Str2Decz1s3	bne z1s4	jmp Dec2Strz1s4	jmp CStr2Dec	ENDP;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File: NewD2S.TEXT;; 6502 number formatter -- implements Pascal Dec2Str;; Status: ALPHA;; Copyright Apple Computer, Inc. 1985;;;; Written by Kenton Hanson, Apple Numerics Group, 8 March 85;; ;; 8 May 86, KLH modified for Cortland Orca assembler;;      ___________________________________________________________;;;; Description: This code is intended to be position independent;;;;;; Const;;    DECSTRLEN = 80;;;    SigDigLen = 28;;; type;;    DecStr   = string [DECSTRLEN];;;    Decimal  = record;;	sgn : 0..1;;;	exp : integer;;;	sig : string [SigDigLen];;               end;;;    DecForm = record;;	style  : (FLOATDecimal, FIXEDDecimal);;;	digits : integer;;               end;;;;;;; Procedure Dec2Str (f : DecForm; d : decimal; var y : DecStr) ; external;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT Dec2StrDec2Str	PROCwmax	equ 80wmaxP1	equ wmax+1wmaxP4	equ wmax+4temp	equ 128fstyle	equ tempfdgts	equ temp+1dst	equ temp+2src	equ temp+6BCD	equ temp+6	; holds BCD intermediate result (3 bytes)DecFrm	equ temp+10sgn	equ DecFrmMinDig	equ temp+11	; minus Minimum digits for NaN or Exponentexp	equ DecFrm+2dsig	equ DecFrm+4frstdig	equ DecFrm+5	ldx #$00z20s0	pla	; pull return and arguments from stack	sta temp,x	inx	inx	cpx #$0e	bne z20s0	lda temp	; push return address back onto stack	pha	longa off	longi off	sep #$30	ldy #$00	lda [DecFrm],y	; get DecForm into memory	sta fstyle	ldy #$02	lda [DecFrm],y	sta fdgts	iny	lda [DecFrm],y	; check that fdgts is a valid signed byte	bmi z20s1	bne ErrXitJ1	; fdgts > 255	lda fdgts	bpl z20s2	bmi ErrXitJ1	; fdgts > 127z20s1	eor #$0ff	bne ErrXitJ1	; fdgts < -256	lda fdgts	bpl ErrXitJ1	; fdgts < -128z20s2	ldy #$5z20s3	lda [src],y	; get first 6 bytes	of Decimal Rec. into memory	tyx	sta sgn,x	dey	bpl z20s3	lda dsig	; get length byte	beq ErrXitJ1	; length = 0 (error)	cmp #$1d	; a - 29.	    <klh 18oct85>	bcs ErrXitJ1	; a >= 29.SgnBlnk	ldy #$00	sec	lda #$2d	; .ascii  '-'	bit sgn	; NOTE: bit instruction does not set 'carry'	bne z21s2	; Obscure, #2d is odd, & has been anded	with sgn	lda fstyle	bne z21s3	; Fixed & postive, no leading character	lda #$20	; .ascii  ' 'z21s2	clc	iny	sta [dst],yz21s3	lda #$03	; offset address of	src by 4 or 3	adc src	sta src	bcc z21s99	inc src+1	bne z21s99	inc src+2	bne z21s99	inc src+3z21s99	lda frstdig	cmp #$3f	; '?'	beq ErrXitJ1	cmp #$30	; '0'	bne z21s4	ldx #$00	stx exp	; exp <- 0	stx exp+1	inx	stx dsig	; length (sig) <- 1	bne Num	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYSz21s4	and #$0df	; turn off upper/lower case bit	cmp #$4E	; .ascii  'N' or 'n'	beq NaN1	; NAN	cmp #$49	; .ascii  'I' or 'i'	bne Num	; zero, normal or denormal number	lda #$49	; 'I'	iny	sta [dst],y	lda #$4e	; 'N'	iny	sta [dst],y	lda #$46	; 'F'	iny	sta [dst],y	bne Fin1	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYSErrXitJ1	lda #$3f	; '?'	ldy #$01	sta [dst],y	tya	deyEx1	sta [dst],y	rep #$30	rtsFin1	tya	ldy #$00	beq Ex1	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYSNum	ldx fstyle	bne BgnFxd;           ;if f.digits < 1 then f.digits := 1;         { ErrXit ???? };           ;s := concat (s, copy (d.sig, 1, 1));;           ;if (f.digits > 1) or (length (d.sig) > 1) then;              ;begin;                 ;s := concat (s, '.');;                 ;if length (d.sig) > 1 then;	     ;s := concat (s, copy (d.sig, 2, length (d.sig) - 1));;                 ;if f.digits > length	(d.sig) then;	                   ;AppendZeros (f.digits - length (d.sig));	iny	; copy one digit before the '.'	lda [src],y	sta [dst],y;           ;if (f.digits > 1) or (length (d.sig) > 1) then	dec dsig	; dsig := dsig - 1	lda fdgts	cmp #$02	; fdgts - 2	bpl z22s1	; fdgts > 1	lda #$01	sta fdgts	ldx dsig	beq z22s5	; dsig = 1z22s1	lda #$2e	; '.'	iny	sta [dst],y	ldx dsig	beq z22s5z22s3	lda [src],y	; copy after the '.'	iny	sta [dst],y	dex	bne z22s3z22s5	lda #$0ff	eor dsig	; a := -dsig	bmi FromFlt	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYSErr1	clc	bcc ErrXitJ1NaN1	beq NaN2BgnFxd	lda exp+1	; check that exp is	a valid signed byte	bmi z23s1	bne ErrXitJ1	; exp > 255	lda exp	bpl BF2	bmi ErrXitJ1	; exp > 127z23s1	eor #$0ff	bne ErrXitJ1	; exp < -256	lda exp	bpl ErrXitJ1	; exp < -128BF2	lda exp	clc	adc dsig	bvs ErrXitJ1	tax	bmi AllAftr	beq AllAftr	lda exp	clc	bpl Before	adc dsigz24s1	iny	; copy before the '.'	lda [src],y	sta [dst],y	dex	bne z24s1	lda #$2e	; '.'	iny	sta [dst],y	ldx expz24s2	lda [src],y	; copy after the '.'	iny	sta [dst],y	inx	bmi z24s2	bpl ApZ	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYSBefore	ldx dsigz25s4	iny	; copy all dsig before the '.'	lda [src],y	sta [dst],y	dex	bne z25s4	tya	adc exp	; carry cleared above	bvs Err1	cmp #wmaxP1	; a - wmaxP1	bpl Err1	ldx exp	beq z25s6	lda #$30	; '0'z25s5	iny	sta [dst],y	dex	bne z25s5	stx expz25s6	cpx fdgts	; x - fdgts	bpl ApZ	; fdgts <= 0	cpy #wmax	; y - wmax	bcs ErrXit	lda #$2e	; '.'	iny	sta [dst],y	bne ApZ	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYSFromFlt	bmi FFltNaN2	beq NaN3AllAftr	dex	txa	inx	clc	adc src	sta src	lda #$0ff	adc src+1	sta src+1	lda #$30	; '0'	iny	sta [dst],y	lda #$2e	; '.'	iny	sta [dst],y	txa	beq z26s16	lda #$30	; '0'z26s15	iny	cpy #wmaxP1	; a - wmaxP1	bcs ErrXit	sta [dst],y	inx	bne z26s15;; adjust the address of source, possibly restructuring ErrXit abovez26s16	tya	clc	adc dsig	cmp #wmaxP1	; a - wmaxP1	bpl ErrXit	ldx dsigz26s17	lda [src],y	; copy all dsig after the '.'	iny	sta [dst],y	dex	bne z26s17;	;if d.exp >= -f.digits then AppendZeros	(f.digits + d.exp);ApZ	lda expFFlt	clc	adc fdgts	bvs ErrXit	;	bmi fine	beq fine	tax	sty temp+1	clc	adc temp+1	cmp #wmaxP1	; a - wmaxP1	bpl ErrXit	lda #$30	; '0'z27s9	iny	sta [dst],y	dex	bne z27s9fine	ldx fstyle	beq BgnExpfin	tya	ldy #$00	sta [dst],y	rep #$30	rtsErrXit	lda #$3f	; '?'	ldy #$01	sta [dst],y	bne fin;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS;;------------------------------------------------------------------------------;;;; change unsigned binary number in exp	into a BCD number in BCD to BCD+2;;;;------------------------------------------------------------------------------NaN3	sta frstdig	iny	sta [dst],y	lda #$41	; 'A'	iny	sta [dst],y	sty MinDig	lda #$4e	; 'N'	iny	sta [dst],y	lda #$28	; '('	iny	sta [dst],y	sty temp+1	; save y	iny	iny	iny	lda #$29	; ')'	iny	sta [dst],y	tya	ldy #$00	sta [dst],y	tya	; initialize exp	ldy MinDig	; restore y	ldx dsig	cpx #$06	; y - wmax	bcc z28s3	; x < 6	ldx #$05z28s3	dex	beq z28s5	asl a	asl a	asl a	asl a	sta exp	lda [src],y	cmp #$40	; a - #40	bcc z28s4	; not a letter	adc #$08z28s4	and #$0f	ora exp	iny	bne z28s3;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS;      ;ldx     #00z28s5	sta exp	lda #$0fc	; -4	bne codeNaN	; branch always;  BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS   BRANCH ALWAYS;           ;STR (d.exp + length (d.sig) - 1, SExp);     { no check for wrap };           ;if SExp [1] <> '-' then SExp := concat ('+', SExp);;           ;if (length (s) + length (SExp)) < Wmax then;		             ;s := concat (s, 'e', SExp);		           ;else ErrXit;BgnExp	cpy #wmaxP4	; a - wmaxP4ErrXit3	bcs ErrXit	lda #$65	; 'e'	iny	sta [dst],y;      ;ldx     #00	            ; set above by 'ldx     fstyle';      ;clc	            ; reset	    by 'cpy     #wmaxP4	lda dsig	adc exp	sta exp	txa	adc exp+1	sta exp+1	bvs ErrXit	; exponent overflows integer value	bmi z29s1	lda #$2b	; '+'	bne z29s2	; branch alwaysz29s1	sec	txa	sbc exp	sta exp	txa	sbc exp+1	sta exp+1	lda #$2d	; '-'z29s2	iny	sta [dst],y	lda #$0fa	; -6	inx	sty temp+1	; save ycodeNaN	sta MinDig	lda #$00	sta BCD	sta BCD+1	sta BCD+2	sedz30s0	ldy #$08	; number of valid bits per bytez30s1	asl exp,x	lda BCD	adc BCD	sta BCD	lda BCD+1	adc BCD+1	sta BCD+1	lda BCD+2	adc BCD+2	sta BCD+2	dey	bne z30s1	dex	bpl z30s0	cld	ldy temp+1	; restore yN2Ascii	ldx #$2z31s1	lda BCD,x	lsr a	lsr a	lsr a	lsr a	beq z31s2	; zero encountered	sta MinDigz31s2	inc MinDig	bmi z31s4	ora #$30	iny	cpy #wmaxP1	; y - wmaxP1z31s3	bcs ErrXit3	sta [dst],yz31s4	lda BCD,x	and #$0f	beq z31s5	; zero encountered	sta MinDigz31s5	inc MinDig	bmi z31s6	ora #$30	iny	cpy #wmaxP1	; y - wmaxP1	bcs z31s3	; ErrXit3	sta [dst],yz31s6	dex	bpl z31s1	lda frstdig	cmp #$4e	beq rts3	tya	ldy #$00	sta [dst],y	longa on	longi onrts3	rep #$30	rts	ENDP	EXPORT CStr2DecCStr2Dec	PROC;          copy sane/str2dec1;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Str2Dec.TEXT;; Decimal string scanner for 6502;; Status: BETA;; Copyright Apple Computer, Inc. 1984,1985;;;; Written by Clayton Lewis, Apple Numerics Group, 27 September 1984;;;; Modification History:;;    14 May 84  JTC  Original 68000 code named ScanDec;;    03 Oct 84  CRL  CStr2Dec entry point for character streams;;    18 Oct 84  CRL  Clean and compact	the code;;    05 Nov 84  CRL  No longer accept Ascii with high bit set;;	  Signalling NaN delivered if no characters accepted;;    15 Jan 85  RwH  (Think) changed .includes for my directory structure.;;	  changed .org to XORG.  Added XEND at end.;;    03 Feb 85  rwh  changed % to ? in	macros...added .ref	FP6502;;    15 feb 85  rwh  deleted .ref FP6502 - its back to being in Think's ORGS;;	  file.;;    16 mar 85  rwh  added .nolists for faster assembly;;    17 May 85  CRL  Bug in State2.  The string '0)' left index in limbo.;;	  Fix in State2 is marked by  {add 4 lines 17 May 85 CRL};;    23 May 85  CRL  Fold in ongoing changes: AppendDigit to ignore characters;;	  after 28th,(13 Mar 85).  NaN signalling bit change at SNaN;;	  and State99 for 68881 and 68000 compatibility, (19 Mar 85);;    19 Jun 85  CRL  Change constant from 2 to 4 in 'State99, process NaNcode'.;;	  Fixes bug in IP; nancode now in correct byte.;;    11 Jul 85  CRL  Bug in state6.  '..' handled wrong.  Fix moves local label;;	  $1 up by three lines, replaces LDA with LDX.;;    29 Aug 85  klh  Butchered to assemble on the ///.;;    18 Oct 85  klh  More mutilation to assemble under ORCA/M.;;     7 May 86  klh  Altered to run in	65816 native mode with 8-bit registers.;;              ________________________________________________;;;; Define storage on zero page and set switches for machine/environment:;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ADDRESSINDIRECT	EQU 128	; start of zero page useREGISTERS	EQU 160VP	EQU ADDRESSINDIRECTD	EQU ADDRESSINDIRECT+4INDEX	EQU ADDRESSINDIRECT+8thisS	EQU ADDRESSINDIRECT+12DSIGLOC	EQU ADDRESSINDIRECT+16CHARPTR	EQU REGISTERS	; ^char interface needs 2 bytesSAVEDCHARPTR	EQU REGISTERS+2LASTCHARPTR	EQU REGISTERS+4NaNCODE	EQU REGISTERS+5FLZERO	EQU REGISTERS+6FLVALPREF	EQU REGISTERS+7FLEXPSGN	EQU REGISTERS+8STACKADJ	EQU REGISTERS+9DSIGLENGTH	EQU REGISTERS+10EXPONENT	EQU REGISTERS+11EXPADJUST	EQU REGISTERS+13STMP	EQU REGISTERS+15CSTRING	EQU REGISTERS+16;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Define constants.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;SIGDIGLEN	EQU 28	; note: 20 for the 68000TAB	EQU $09BLANK	EQU $20OPENPAREN	EQU $28CLOSEPAREN	EQU $29PLUS	EQU $2BMINUS	EQU $2DDOT	EQU $2EZERO	EQU $30ONE	EQU $31FOUR	EQU $34	; {addition 23 May 85  CRL}NINE	EQU $39COLON	EQU $3ABIGA	EQU $41E	EQU $45F	EQU $46I	EQU $49N	EQU $4ESMALLa	EQU $61SMALLe	EQU $65zPLUS1	EQU $7B;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Start of routine, note the 2 entry points:  Str2Dec and CStr2Dec.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	LDX #$0	JMP Start2	EXPORT Str2DecStr2Dec		;       	LDX #$1;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Save items passed on the stack and initialize flags.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;start2	STX CSTRING	; no length byte if	CSTRING is 0	ply	LDX #$0	; first save 16 bytes from stackz2s1	PLA	STA ADDRESSINDIRECT,X	INX	inx	CPX #16	BCC z2s1	phy	LDX #$10	; 16 slots to zeroz2s2	DEX	dex	STz REGISTERS,X	BNE z2s2	TxY	; putting 0 into Y	longa off	longi off	sep #$30	LDA [INDEX],Y	STA CHARPTR	; offset from start	of S	STA SAVEDCHARPTR	LDX CSTRING	BEQ z2s3	LDA [thisS],Y	; length byte of S	STA LASTCHARPTR	; offset from start	of S	INY	; Y now has 1	LDA [INDEX],Y	; look at hi byte of index	BEQ z2s5	;    OK if zero	JMP StateFin	;    exit if index too largez2s3	INY	; keep the hi byte of index also	LDA [INDEX],Y	STA CHARPTR+1	STA SAVEDCHARPTR+1	CLC	; then advance the same number of	ADC thisS+1	;    pages into the	buffer S so	STA thisS+1	;    Y can index into next pagez2s5	CLC	; set up pointer to	d.sig	LDA D	;    4 bytes into D	ADC #$4	STA DSIGLOC	LDA D+1	ADC #$0	STA DSIGLOC+1	LDA D+2	ADC #$0	STA DSIGLOC+2	LDA D+3	ADC #$0	STA DSIGLOC+3;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Initialize the decimal record to sign +, EXPONENT 0 and significand N0011.;;      Use SNaN = 00 00 00 00 05 4E 30	30 31 31  = (0)(0)(0)(0)(5)'N0011';;      {change only to comment: 23 May	85 CRL, signaling NaN bit change};;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;InitDec	LDY #$9z3s1	LDA SNaN,Y	; data for SNaN at end of file	STA [D],Y	DEY	BPL z3s1;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State0 -- scan leading white space.	Blanks and tab characters.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State0	JSR GetChar	CMP #BLANK	; blank	BEQ State0	CMP #TAB	; tab	BEQ State0;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Then fall through to State1 looking for a sign.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State1	CMP #PLUS	BEQ z4s1	; +, go on since d.sgn already = 0	CMP #MINUS	BNE State2	; not +/-, check for number	LDA #$1	; -, so store 0001 in d.sgn	LDY #$0	STA [D],Y	TYA	INY	STA [D],Yz4s1	JSR GetChar;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Now expect to have INF, NaN, or number.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State2	CMP #ZERO	; look for leading zeros	BCC z5s1	;    character < '0'z5s0	BNE z5s2	;    character > '0'	SEC	ROL FLZERO	; zero seen, set lo	bit of FLZERO	JSR ClearSavedPtr	; use current scan pointer	JSR GetChar	; try again with a new character	BCS z5s0	; branch if char is	'0' or greaterz5s1	CMP #DOT	; only interesting character < 0	BEQ State6	; dot found before signif digits;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; {Add 4 lines 17 May 85 CRL};       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	LDA FLZERO	BEQ z5s3	JMP StateNumz5s3	JMP StateBackup	; illegitimate numberz5s2	CMP #COLON	BCC State4	; digits follow, go	scan them	LDY FLZERO	; any leading zero's?	BNE GoTo8	;    if so, try E,e	JMP State99	;    if not, try INF, NaNGoTo8	JMP State8;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State4 -- Scan significant digits before the decimal point.  Uses;;      AppendDigit	to place digit in string, get next character, and;;      compare next character to 0.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State4	JSR ClearSavedPtr	; use current scan pointerz6s1	JSR AppendDigit	BCC State5	; character < '0', so look for dot	CMP #COLON	; one greater than '9'	BCC z6s1	; =< 3A,   so character in 0..9;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State5 -- check for start of fraction field after some significant;;      digits have	already been scanned.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State5	CMP #DOT	BNE GoTo8	; try EXPONENT field (State8)	JSR GetChar	BCS z7s1	; potential digits	JMP StateNum	; dot followed by no digits, endz7s1	JMP State75;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; AppendDigit;;      - Place numeral in digit field of decimal;;      - Get next character;;      - Compare with '0' before returning;;        {remove last comment: 13 Mar 85 CRL};;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AppendDigit	LDY DSIGLENGTH	CPY #SIGDIGLEN	; past all valid digits?	BCS z8s3	;    if so, just count lost digits	INY	;    if not, advance pointer	STY DSIGLENGTH	;    and store digit in d.sig	STA [DSIGLOC],Y	BNE GetChar	; always;{13 Mar 85 CRL}	   ORA     @DSIGLOC,Y   ; OR into 28th digit;{13 Mar 85 CRL}	   STA     @DSIGLOC,Yz8s3	INC EXPADJUST	; record the # of lost digits	BNE GetChar	INC EXPADJUST+1;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; GetChar;;      - STACKADJ <-- # bytes of return addresses on stack;;      - Check for	end of scanning string;;      - Collect next character (if not at string end);;      - Set ValidPrefix to TRUE if at	string end;;      - See if saved instead of current pointer should be	returned;;;; Note the two entry points.  GETCHAR2	is called by GETMAPPED with 4 in A.;;      Since GETMAPPED calls via JSR, there are two return	addresses;;      to pop if scan ends prematurely	and we do not return to caller.;;      Other calls	need to pop only one return address.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;GetChar	LDA #$2	; stack adjustment if abortGetChar2	STA STACKADJ	JSR CheckEndScan	; end of scan?	BCC z9s7	;    if so, branch	LDY CHARPTR	;    else get next character	LDA [thisS],Y	INC CHARPTR	BNE z9s5	INC CHARPTR+1	INC thisS+1z9s5	CMP #ZERO	RTSz9s7	INC FLVALPREF	; premature string end	LDY STACKADJ	; pop return address(es)z9s9	PLA	DEY	BNE z9s9	LDY SAVEDCHARPTR+1	; has a pointer been saved?	BMI z9s11	;    if not, just exit	JMP StateBackup	;    else reset ptr, then exitz9s11	JMP StNum2;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State6 -- encountered dot before any	nonzero significant	digits.  Keep;; looking for digits, but throw away leading zeros, remembering placement;; of decimal.  If possible nonzero digit or letter, skip right into fraction;; digit scanner.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State6	JSR GetChar	; skip past dot	BEQ z10s3	; if zero, branch	BCC z10s1	; if less than zero, end	CMP #COLON	; > zero, but is it	9 or less?	BCC State7	;    if 1..9, next state;       ;; Local label $1 moved to next	line from previous location;       ;;   4 lines down between two JMP instructions.;       ;; Change next instruction to LDX instead of LDA.	11 July 85  CRLz10s1	LDX FLZERO	; no digits, were there 0's?	BNE State8	;    if so, try E,e	JMP StateBackup	;    else return to	begin of scan	JMP StateNumz10s3	SEC	ROL FLZERO	; character = '0', set flag	JSR ClearSavedPtr	; use current character pointer	LDX expadjust	BNE z10s12	DEC expadjust+1z10s12	DEC expadjust	BNE State6	; and look for more	0's  (always);          copy sane/str2dec2;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State7 -- scan fraction digits.  Use	AppendDigit and keep count of the;; number of digits	scanned, whether in	excess of 28 or not.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State7	JSR ClearSavedPtr	; use current character pointer	LDX expadjust	; count number of fraction digits	BNE z11s12	DEC expadjust+1z11s12	DEC expadjust	JSR AppendDigit	BCS State75	; if > zero, keep looking	JMP StateNum	;    else doneState75	CMP #COLON	; exit if character	> '9'	BCC State7;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State8 -- look for EXPONENT: E or e followed be optional	sign and a digit;; field.  Must be careful about EXPONENT overflow.  Since the extended;; range admits values in magnitude between 10^-5000 and 10^5000, it;; suffices to check for EXPONENT outside 4096 + 1024 = 5120.  Overflowed;; EXPONENT are mapped into $1400 (5120), guaranteed to produce a severe;; overflow on conversion.;;;; Must also guard against overscan of expressions like '123e-'.  We must;; return 123 with pointer at 'e'.  If E or e is found, hold input pointer;; in case subsequent scanning does not	make sense of the characters past;; '123'.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State8	JSR UpdatePtr	; save current character pointer	LDX savedcharptr	; and move it back by one	BNE z12s12	DEC savedcharptr+1z12s12	DEC savedcharptr	CMP #E	BEQ z12s1	CMP #SMALLe	BNE z12s15	; no EXPONENT foundz12s1	JSR GetChar	CMP #PLUS	BEQ z12s3	CMP #MINUS	BNE z12s5	INC FLEXPSGN	; mark as negative EXPONENTz12s3	JSR GetChar	; skip past sign characterz12s5	CMP #ZERO	; >= '0'?	BCC z12s15	;   if not, end digit field	CMP #COLON	; =< '9'?	BCS z12s15	;   if not, end  digit field	JSR ClearSavedPtr	; digit, use current char pointer	AND #$0F	; mask to nibble	TAX	; hold digit in X until end of loop;          ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;          ;; Multiply EXPONENT by 10;          ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	ASL EXPONENT	; first multiply by	2	ROL EXPONENT+1	;   EXPONENT word *	2	LDA EXPONENT+1	STA STMP	; copy to A register and STMP	LDA EXPONENT	;   then multiply those by 4	ASL A	;   to get EXPONENT	* 8	ROL STMP	ASL A	ROL STMP	; note that carry is not set so...	ADC EXPONENT	; now add Exp * 2 +	Exp * 8	STA EXPONENT	;    to get EXPONENT * 10	LDA STMP	ADC EXPONENT+1	STA EXPONENT+1;          ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;          ;; And add in the current digit.;          ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	CLC	TXA	; pick up digit from X	ADC EXPONENT	STA EXPONENT	BCC z12s9	INC EXPONENT+1z12s9	LDA #$14	CMP EXPONENT+1	; EXPONENT >= 5120?	(overflow)	BCS z12s13	;    if not, continue	STA EXPONENT+1	;    else just use 5120z12s13	JMP z12s3;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; Finish scan by checking to see whether we have overscanned.;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;z12s15	LDY SAVEDCHARPTR+1	; overscan?	BMI StateNum	;    if not, go on	JMP StateBackup	;    if so, reset pointer;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; StateNum -- have	sighted the first unrecognizable character after a;; possible number.	 Check first for 0,	a special case since all digits;; were discarded above, then put the number in canonical form.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;StateNum	LDX charptr	BNE z13s12	DEC charptr+1z13s12	DEC charptrStNum2	LDY #$0	; needed at $2 and 5 lines down	LDA DSIGLENGTH	; any digits?	BNE z14s2	;    if so, branch	LDA FLZERO	;    if none, 0?	BEQ StateFin	;       not even 0!! (branch always)	LDA #$1	; if 0, then return	d.sig = 0	STA [DSIGLOC],Y	; length byte of 1 in d.sib	INY	LDA #$30	; then the '0' character	STA [DSIGLOC],Y	BNE StateFin	; always;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; Have nonzero number with:;       ;;      - DSIGLENGTH digits;       ;;      - Positive binary exponent in EXPONENT, EXPONENT+1;       ;;      - Lost digit count minus fraction digit count in EXPADJUST;       ;;;       ;; To align	decimal point at the end of d.sig, compute:;       ;;      true exponent := EXPONENT + EXPADJUST.;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;z14s2	STA [DSIGLOC],Y	; put length byte in d.sig	LDA FLEXPSGN	; negative exponent?	BEQ z14s5	;    if not, branch;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; Negate the integer EXPONENT.;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	SEC	LDA #$0	SBC EXPONENT	STA EXPONENT	LDA #$0	SBC EXPONENT+1	STA EXPONENT+1;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; Finish up with the final addition.;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;z14s5	LDY #$2	; d.exp occupies bytes 2 & 3 of D	CLC	LDA EXPONENT	ADC EXPADJUST	STA [D],Y	; store the lo byte	INY	LDA EXPONENT+1	ADC EXPADJUST+1	STA [D],Y	; store the hi byte;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; StateFin -- replace the updated input pointer INDEX, set	the final value;; of VALIDPREFIX, and RTS through the return address.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;StateFin	LDY #$0	LDA CHARPTR	STA [INDEX],Y	LDA FLVALPREF	; store the low byte	STA [VP],Y	TYA	; and zero out the hi byte	INY	STA [VP],Y	LDA CHARPTR+1	sta [INDEX],Y	rep #$30	RTS;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; State99 -- all else has failed, so check for INF and NaN.  Use the saved;; character pointer to back up in case	a partial scan does	not find the;; full token for a	NaN.  INF is handled at StateINF.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;State99	LDX charptr	BNE z15s12	DEC charptr+1z15s12	DEC charptr	JSR GetMapped	CMP #I	; test for 'I'	BNE z15s1	;    if not, branch	JMP StateINF	;    if so, try 'INF'z15s1	CMP #N	;    else try 'N'	BNE StateBackup	; if neither, quit looking	JSR GetMapped	CMP #BIGA	BNE StateBackup	JSR GetMapped	CMP #N	BNE StateBackup;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; NaN found.  Replace N0011 with N4000 as default NaN.;       ;; {changed	23 May 85  CRL : new sense of signalling NaN bit};       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	LDY #$2	LDA #FOUR	STA [DSIGLOC],Y	; '4' as first digit	LDA #ZERO	; prepare to zero out the '11' chars	INY	INY	STA [DSIGLOC],Y	INY	STA [DSIGLOC],Y;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; Expect string (xxxx) to follow NaN.  Check for it and;       ;; translate to a two digit ascii code in hex.  Save the pointer;       ;; at NAN in case junk follows.;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	JSR UpdatePtr	; advance pointer to NAN	JSR GetChar	CMP #OPENPAREN	BNE StateBackup	; if no '(' then leavez15s49	JSR GetChar	BCC z15s57	; < '0' so check for ')'	CMP #COLON	; > '9' so junk	BCS StateBackup	AND #$0F	; mask to 0..9	STA STMP	;    and hold digit	until later;          ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;          ;; Multiply NaNCODE by 10 and add in next digit found.;          ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	ASL NaNCODE	; * 2	LDA NaNCODE	ASL A	ASL A	; * 8	CLC	ADC NaNCODE	; sum to get NaNCODE * 10	CLC	ADC STMP	; add in next digit	STA NaNCODE	JMP z15s49	; and keep looking;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; End of numeric scan.  Now look for the final ')'.;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	JSR GetCharz15s57	CMP #CLOSEPAREN	; end with  ')'?	BNE StateBackup	; if no ')', back up pointer;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;       ;; Process NaNCODE and put two ascii hex characters	in d.sig;       ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	LDA NaNCODE	LSR A	LSR A	LSR A	LSR A	JSR NibOut	; process hi byte	LDY #$4	; {CRL19jun85} PUT NAN CODE IN RIGHT PLACE	STA [DSIGLOC],Y	; and store the ascii	LDA NaNCODE	AND #$0F	JSR NibOut	; process lo byte	INY	STA [DSIGLOC],Y	; and store the ascii	BNE INF3	; always;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; StateBackup -- if the string has been overscanned, then SAVEDCHARPTR;; contains the index of the last valid	substring.  In this	case, revert to;; the saved pointer and then branch to	the output routine.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;StateBackup	LDX SAVEDCHARPTR	STX CHARPTR	LDX SAVEDCHARPTR+1	STX CHARPTR+1	JMP StNum2	; always;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; StateINF -- look	for simple string 'INF'.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;StateINF	JSR GetMapped	CMP #N	BNE StateBackup	JSR GetMapped	CMP #F	BNE StateBackup	LDY #$0	LDA #$1	STA [DSIGLOC],Y	; length byte of 1	LDA #I	; put I into d.sig	INY	STA [DSIGLOC],YINF3	JSR ClearSavedPtr	; use current pointer	JSR CheckEndScan	; end of scan?	BCS z16s7	;    if not, branch	INC FLVALPREF	;    if so, set flagz16s7	JMP StateFin;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; GetMapped -- fetches next input character, maps to upper	case.  Note;; that upper and lower case letters differ only in bit #5.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;GetMapped	LDA #$4	; stack adjust in GetChar	JSR GetChar2	CMP #SMALLa	BCC z17s1	; too small for lower case	CMP #zPLUS1	; one past 'z'	BCS z17s1	; too big for lower	case	AND #$0DF	; mask 1101 1111 for bit 5z17s1	RTS;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; NibOut -- passed	a nibble in the accumulator, construct an ascii;; character of it.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;NibOut	CMP #$0a	;<klh 18oct85>	BCC z18s1	; 0..9	ADC #$6	; A..F offset is $37 (6 + carry)z18s1	ADC #$30	; 0..9 offset is $30	RTS;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; The subroutines which control the current value of the scan pointer;;      and the current value of its backup which is used after overscanning.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ClearSavedPtr	LDX #$0FF	STX SAVEDCHARPTR	STX SAVEDCHARPTR+1	RTSUpdatePtr	LDX CHARPTR	STX SAVEDCHARPTR	LDX CHARPTR+1	STX SAVEDCHARPTR+1	RTSCheckEndScan	LDX CSTRING	BEQ z19s3	LDX LASTCHARPTR	CPX CHARPTR;      ;JMP     $5	rts	; <klh 18oct85>z19s3	SEC	LDY CHARPTR	LDA [thisS],Y	BNE z19s5	CLCz19s5	RTS	EXPORT SNaNSNaN	DC.B $00,$00,$00,$00,$05,$4E,$30,$30,$31,$31 ;{SNaN bit change 23May85 CRL}	longa on	longi on	ENDP	END